$i = 0
foreach ($x in $list) { $i++; $out = Join-Path $base $x[0]; if (-not (Test-Path $out) -or (Get-Item $out).Length -lt 1000) { Invoke-WebRequest -Uri $x[1] -OutFile $out -UseBasicParsing }; Write-Progress -Activity "Saving Codex images" -Status "$i of $($list.Count)" -PercentComplete ($i * 100 / $list.Count) }
$first = Get-ChildItem (Join-Path $base "cards") -Filter *.png | Select-Object -First 1; if ($first) { Copy-Item $first.FullName (Join-Path $base "probe.png") -Force }
Write-Host "Done. Reopen riftbound-codex.html."
